<?php require 'includes/layout.php';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['username']??'');$email=trim($_POST['email']??'');$pass=$_POST['password']??'';if(strlen($name)<3||strlen($name)>50||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<8){$error='Use a username of 3–50 characters, valid email, and password of 8+ characters.';}else{try{$s=db()->prepare('INSERT INTO users(username,email,password_hash) VALUES(?,?,?)');$s->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT)]);flash('Account created. Please log in.');redirect('login.php');}catch(PDOException $ex){$error='Username or email is already taken.';}}}top('Create Account'); ?><div class="panel"><?php if(isset($error)):?><p class="error"><?=e($error)?></p><?php endif;?><form class="form" method="post"><?php csrf_field();?><label>Username<input name="username" required minlength="3" maxlength="50"></label><label>Email<input type="email" name="email" required></label><label>Password<input type="password" name="password" required minlength="8"></label><button class="btn">Register</button></form><p>Already a member? <a href="login.php">Log in</a></p></div><?php bottom(); ?>